using System.Text.Json;
using EmberLighthouse.Core;
using EmberLighthouse.Items;
using EmberLighthouse.Persistence;
using EmberLighthouse.Rendering;
using EmberLighthouse.World;
public static class ExplorationTests
{
    public static void Run(Catalog catalog,Action<string,Action> test,string root)
    {
        void Check(bool ok,string message){if(!ok)throw new Exception(message);}
        test("delete old and damaged worlds, isolate saves, restore unchanged and reject unsafe paths",()=>{
            var store=new SaveStore(Path.Combine(root,"deletion","worlds"),catalog);var old=new WorldSnapshot{GeneratorVersion=2,Name="旧存档"};old.Changes["5,50,5"]="plank";old.Inventory.Add("iron_pick",1,catalog);store.Save(old);var other=new WorldSnapshot{Name="保留世界"};store.Save(other);
            var files=Directory.GetFiles(Path.Combine(store.Root,old.WorldId),"*",SearchOption.AllDirectories).ToDictionary(p=>Path.GetRelativePath(Path.Combine(store.Root,old.WorldId),p),File.ReadAllBytes);
            using(var busy=new FileStream(Path.Combine(store.Root,old.WorldId,".saving.lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None)){bool refused=false;try{store.DeleteWorld(old.WorldId,old.Name);}catch(IOException){refused=true;}Check(refused&&!File.Exists(Path.Combine(store.Root,old.WorldId,"DELETED.info")),"active save lock ignored or deletion marker leaked");}
            string deleted=store.DeleteWorld(old.WorldId,old.Name);Check(!Directory.Exists(Path.Combine(store.Root,old.WorldId))&&store.ListDetails().Single().Id==other.WorldId,"deleted save remains or neighbor lost");Check(store.ListDeletedWorlds().Single().Id==old.WorldId,"trash record absent");
            Check(store.RestoreDeletedWorld(deleted)==old.WorldId,"restore changed identity");var loaded=store.Load(old.WorldId).Snapshot;Check(loaded.GeneratorVersion==2&&loaded.Changes["5,50,5"]=="plank"&&loaded.Inventory.Count("iron_pick")==1,"restore changed old terrain or progress");
            foreach(var (path,bytes) in files)Check(File.ReadAllBytes(Path.Combine(store.Root,old.WorldId,path)).SequenceEqual(bytes),"save bytes changed during delete/restore");
            var damaged=new WorldSnapshot();Directory.CreateDirectory(Path.Combine(store.Root,damaged.WorldId));File.WriteAllText(Path.Combine(store.Root,damaged.WorldId,"CURRENT"),"broken");deleted=store.DeleteWorld(damaged.WorldId,"损坏世界");Check(store.ListDetails().All(e=>e.Id!=damaged.WorldId),"damaged save cannot be deleted");store.RestoreDeletedWorld(deleted);Check(File.ReadAllText(Path.Combine(store.Root,damaged.WorldId,"CURRENT"))=="broken","damaged original changed");
            foreach(string bad in new[]{"..","../worlds","C:\\",old.WorldId+"/../"}){bool refused=false;try{store.DeleteWorld(bad,"x");}catch(ArgumentException){refused=true;}Check(refused,"unsafe world ID accepted");}
            deleted=store.DeleteWorld(old.WorldId,old.Name);store.Save(old);bool blocked=false;try{store.RestoreDeletedWorld(deleted);}catch(InvalidOperationException){blocked=true;}Check(blocked&&store.Load(old.WorldId).Snapshot.Name==old.Name,"restore overwrote existing live world");
        });
        test("chest weighted loot varies with seed, region and cell while persistence never refills",()=>{
            string Serialize(Inventory i)=>JsonSerializer.Serialize(i,Catalog.JsonOptions);var w=new WorldState(catalog,new(){Seed=42});var signatures=new HashSet<string>();
            for(int i=0;i<120;i++){var cell=new Cell(i*13,50,-i*9);var a=ChestLoot.Generate(w,cell);var b=ChestLoot.Generate(w,cell);Check(Serialize(a.Items)==Serialize(b.Items),"loot nondeterministic");Check(a.Items.Slots.Count(s=>s!=null) is >=4 and <=6,"random slot count outside range");Check(a.Items.Slots.Where(s=>s!=null).All(s=>s!.Count>0&&s.Count<=catalog.Items[s.Id].Stack&&s.Id is not("dawn_heart" or "beacon_sigil" or "ember_sword")),"invalid count or quest reward in random chest");signatures.Add(Serialize(a.Items));}
            Check(signatures.Count>90,"chests remain repetitive");var starter=new Cell(34,38,26);w.Set(starter,catalog.Number("chest"));var chest=ChestLoot.Open(w,starter);Check(chest.Storage.Count("map")==1&&chest.Storage.Count("grain")>=2&&chest.Storage.Count("carrot")>=2&&chest.Storage.Count("potato")>=2,"starter crops lost");chest.Storage=new();Check(ChestLoot.Open(w,starter).Storage.Slots.All(s=>s==null),"empty chest refilled");
            foreach(string id in new[]{"mine","forge","snow","cave","vault"}){var site=w.Terrain.Adventure!.Site(id);Check(ChestLoot.Generate(w,site.At(0,1,0)).Theme!= "野外行囊","site supplies ignored");}
            var placed=new Cell(3,37,0);w.State.Inventory.Add("chest",1,catalog);Check(w.Place(placed,"chest",false,out _),"placed setup");Check(ChestLoot.Open(w,placed).Storage.Slots.All(s=>s==null),"player chest gained loot");
            var store=new SaveStore(Path.Combine(root,"loot","worlds"),catalog);store.Save(w.State);var restored=new WorldState(catalog,store.Load(w.State.WorldId).Snapshot);Check(ChestLoot.Open(restored,starter).Storage.Slots.All(s=>s==null)&&restored.State.Entities[starter.ToString()].LootTheme==chest.LootTheme,"save reset loot");
        });
        test("quest graph mirrors branch convergence, locked prerequisites and completion",()=>{
            var w=new WorldState(catalog,new());QuestNode Node(string id)=>QuestJournal.Build(w).Single(n=>n.Id==id);
            Check(Node("mine").Status==QuestStatus.Available&&Node("tower0").Status==QuestStatus.Locked&&Node("forge").Status==QuestStatus.Locked,"initial unlocks wrong");w.State.Mainline.Proofs.Add("mine");Check(Node("tower0").Status==QuestStatus.Available,"mine prerequisite ignored");w.State.Beacons.Add(0);Check(Node("forge").Status==QuestStatus.Available&&Node("snow").Status==QuestStatus.Available,"branch pair not unlocked");w.State.Mainline.Proofs.Add("forge");Check(Node("tower1").Status==QuestStatus.Locked,"one prism skipped convergence");w.State.Mainline.Proofs.Add("snow");Check(Node("tower1").Status==QuestStatus.Available,"two prisms failed convergence");w.State.Beacons.UnionWith([1,2]);w.State.Mainline.Proofs.Add("guardian");w.State.Mainline.Nodes.UnionWith(["bridge","reflector"]);Check(Node("colossus").Status==QuestStatus.Locked&&Node("guard").Status==QuestStatus.Available,"partial vault unlocked boss");w.State.Mainline.Nodes.Add("guard");Check(Node("colossus").Status==QuestStatus.Available,"all circuits failed unlock");w.State.Mainline.Completed=true;Check(QuestJournal.Current(QuestJournal.Build(w)).Id=="dawn"&&Node("dawn").Done,"completion current target wrong");Check(QuestJournal.Edges(QuestJournal.Build(w)).Contains(("forge","tower1"))&&QuestJournal.Edges(QuestJournal.Build(w)).Contains(("snow","tower1"))&&QuestJournal.Edges(QuestJournal.Build(w)).Contains(("vault","guard")),"graph dependency edges missing");
        });
        test("generator four has six distinct safe starts, seed determinism and varied vegetation",()=>{
            var profiles=new Dictionary<int,int>();for(int seed=0;seed<100;seed++){profiles.TryAdd(Landscape.StartProfile(seed),seed);var t=new Terrain(seed,catalog,4);Check(t.Surface(0,0)==36&&catalog.Id(t.Get(new(-4,37,4)))=="wood"&&catalog.Id(t.Get(new(4,37,4)))=="loose_stone"&&catalog.Id(t.Get(new(34,38,26)))=="chest","safe start missing");}
            Check(profiles.Count==6,"some start profiles unreachable");var signatures=new HashSet<string>();var plants=new HashSet<string>();var logs=new HashSet<string>();int low=191,high=0;
            foreach(int seed in profiles.Values){var t=new Terrain(seed,catalog,4);var duplicate=new Terrain(seed,catalog,4);var heights=new List<int>();for(int x=-100;x<=100;x+=4)for(int z=-100;z<=100;z+=4){int h=t.Surface(x,z);heights.Add(h);low=Math.Min(low,h);high=Math.Max(high,h);Check(h==duplicate.Surface(x,z),"surface differs for same seed");for(int dy=1;dy<=12;dy++){string id=catalog.Id(t.Get(new(x,h+dy,z)));if(PlantVisuals.Style(id)>0)plants.Add(id);if(id.EndsWith("_log"))logs.Add(id);}}
                signatures.Add(string.Join(",",heights));}
            var forest=new Terrain(profiles[0],catalog,4);for(int x=20;x<=75;x++)for(int z=20;z<=75;z++){string id=catalog.Id(forest.Get(new(x,forest.Surface(x,z)+1,z)));if(id.EndsWith("_log"))logs.Add(id);}
            Check(signatures.Count==6&&low<34&&high>80,"terrain lacks varied water/mountains or starts");Check(plants.Count==8&&logs.Count==3,"plant or tree species absent: "+string.Join(",",plants)+" / "+string.Join(",",logs));
            foreach(int seed in profiles.Values)for(int x=-520;x<=520;x+=23)for(int z=-520;z<=520;z+=23)Check(Math.Abs(Landscape.Height(seed,x,z)-Landscape.Height(seed,x+1,z))<=6&&Math.Abs(Landscape.Height(seed,x,z)-Landscape.Height(seed,x,z+1))<=6,"regional height seam forms a cliff");
            var legacy=new Terrain(42,catalog,3);Check(legacy.Biome(0,0)==1&&legacy.Surface(0,0)==36,"legacy generator changed");for(int x=-30;x<30;x+=3)for(int z=-30;z<30;z+=3){int h=legacy.Surface(x,z);Check(!catalog.Id(legacy.Get(new(x,h+1,z))).EndsWith("_log"),"new plants leaked into old terrain");}
        });
        test("legacy journal preserves original parallel towers and guardian without new quest gates",()=>{
            foreach(int version in new[]{1,2}){var w=new WorldState(catalog,new(){GeneratorVersion=version});var nodes=QuestJournal.Build(w);Check(nodes.Count==7&&nodes.All(n=>n.Id is not("colossus" or "forge" or "snow")),"new quest leaked into legacy route");Check(nodes.Single(n=>n.Id=="guardian").Status==QuestStatus.Available,"legacy guardian acquired a gate");w.State.Beacons.UnionWith([0,2]);w.State.Inventory.Add("beacon_sigil",1,catalog);nodes=QuestJournal.Build(w);Check(nodes.Single(n=>n.Id=="tower1").Status==QuestStatus.Available&&nodes.Single(n=>n.Id=="dawn").Status==QuestStatus.Locked,"legacy tower order restricted or partial progress completed");w.State.Beacons.Add(1);w.State.GuardianDefeated=true;Check(QuestJournal.Current(QuestJournal.Build(w)).Id=="dawn"&&QuestJournal.Build(w).Single(n=>n.Id=="dawn").Done,"legacy completion absent");}
        });
        test("new plants use distinct atlas cells without collision and trunks harvest common wood",()=>{
            foreach(string id in new[]{"tall_grass","dry_grass","fern","reed","red_flower","blue_flower","brown_mushroom","red_mushroom"}){ushort block=catalog.Number(id);var mesh=VoxelMesher.Build(p=>p==new Cell(0,0,0)?block:(ushort)0,new(0,0,0),catalog);Check(mesh.PlantVertices.Count==8&&mesh.Collision.Count==0,"plant collider or missing crossed sprite");float u=PlantVisuals.Style(id)/(float)PlantVisuals.Count;Check(mesh.PlantVertices.Min(v=>v.U)==u&&Math.Abs(mesh.PlantVertices.Max(v=>v.Y)-PlantVisuals.Height(id))<.001,"wrong atlas cell or height");}
            var w=new WorldState(catalog,new());foreach(string id in new[]{"birch_log","pine_log","acacia_log"}){var p=new Cell(1,90,1);w.Set(p,catalog.Number(id));Check(MiningRules.RequiredTool(catalog.Items[id])=="axe"&&w.Break(p,3,out _),"new trunk harvest failed");}Check(w.State.Inventory.Count("wood")==0&&w.State.Graves.Sum(g=>g.Items.Count("wood"))==3,"new trunks broke crafting progression");
        });
    }
}

